*, *::before, *::after { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  color: var(--text);
  font-family: 'Inter', ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  font-feature-settings: "ss01", "cv11";
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  /* Default = mood-first view (scrollable). Research mode adds .view-research and reverts. */
  overflow-y: auto;
  overflow-x: hidden;
  background:
    radial-gradient(ellipse 60% 45% at 50% -10%, rgba(180, 83, 9, .14), transparent 65%),
    linear-gradient(180deg, var(--bg-0) 0%, #100920 100%);
  background-attachment: fixed;
}

/* Research-mode body locks scroll so the two-panel layout fits the viewport */
body.view-research {
  overflow: hidden;
}
body.view-research .app { height: 100vh; gap: 14px; }
body.view-mood .app     { height: auto; min-height: 100vh; }
body.view-mood .results,
body.view-mood .stickyTop,
body.view-mood .footer { display: none; }
body.view-research .moodHero { display: none; }

/* Subtle film-grain — kills banding on the dark gradient */

