/* Section cards */
.syn-sections {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.syn-section {
  border-radius: 9px;
  border: 1px solid var(--border);
  overflow: hidden;
}
.syn-section-header {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 14px;
  background: color-mix(in srgb, var(--surface) 60%, var(--bg));
  cursor: pointer;
  user-select: none;
  list-style: none;
  font-size: .88rem;
  font-weight: 600;
  color: var(--text);
}
.syn-section-header::-webkit-details-marker { display: none; }
.syn-section[open] .syn-section-header {
  border-bottom: 1px solid var(--border);
}
.syn-icon { font-size: .95rem; }
.syn-title { flex: 1; }
.syn-type-badge {
  font-size: .67rem;
  font-weight: 700;
  letter-spacing: .4px;
  text-transform: uppercase;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  padding: 2px 8px;
  border-radius: 20px;
  border: 1px solid color-mix(in srgb, var(--accent) 25%, transparent);
}

/* Points list */
.syn-points {
  list-style: none;
  margin: 0;
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;

