    'siddiqoon truthful',
    'shuhadaa martyrs',
    'abrar righteous pious',
    'mufsidoon corruptors fasad',
    'mustadhafeen oppressed weak',
    'ulul albab people of understanding',
  ];
  const seen = new Set();
  const pool = [];
  for (const term of GROUPS) {
    try {
      const { results } = await this.engine.search(term, {}, 8);
